    private static readonly Dictionary<string, MaterialIconItem> IconMap =
        Icons.ToDictionary(i => i.Id, StringComparer.OrdinalIgnoreCase);

    public static bool TryGetIcon(string? id, out MaterialIconItem item)
    {
        if (string.IsNullOrWhiteSpace(id))
        {
            item = Icons[0];
            return false;
        }
        return IconMap.TryGetValue(id, out item!);
    }

    public static string GetPathData(string? id)
    {
        if (TryGetIcon(id, out var icon)) return icon.Data;
        return Icons[0].Data;
    }
